-- DEV-002 V006 | worship/prayer/learn/serve/events/care/content metadata
BEGIN;
CREATE TABLE church_module.worship_service_template(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),name text NOT NULL,canonical_liturgy_ref text,version integer NOT NULL DEFAULT 1);
CREATE TABLE church_module.worship_service(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),campus_id uuid REFERENCES church_tenant.campus(id),template_id uuid REFERENCES church_module.worship_service_template(id),starts_at timestamptz NOT NULL,status text NOT NULL,stream_ref text);
CREATE TABLE church_module.worship_participation(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),service_id uuid NOT NULL REFERENCES church_module.worship_service(id),membership_id uuid NOT NULL REFERENCES church_community.church_membership(id),attendance_status text NOT NULL,source text);
CREATE TABLE church_module.prayer_request(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),owner_person_id uuid NOT NULL REFERENCES church_identity.person(id),category text,status text NOT NULL,visibility text NOT NULL,content_ref text);
CREATE TABLE church_module.prayer_share(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),request_id uuid NOT NULL REFERENCES church_module.prayer_request(id),recipient_scope text NOT NULL,expires_at timestamptz);
CREATE TABLE church_module.prayer_commitment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),request_id uuid NOT NULL REFERENCES church_module.prayer_request(id),supporter_id uuid NOT NULL REFERENCES church_identity.person(id),status text NOT NULL);
CREATE TABLE church_module.care_request(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),owner_person_id uuid REFERENCES church_identity.person(id),category text,status text NOT NULL,content_ref text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE church_module.care_assignment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),care_request_id uuid NOT NULL REFERENCES church_module.care_request(id),assignee_person_id uuid REFERENCES church_identity.person(id),due_at timestamptz,status text NOT NULL);
CREATE TABLE church_module.program_offering(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),curriculum_id text NOT NULL,title text NOT NULL,status text NOT NULL);
CREATE TABLE church_module.cohort(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),offering_id uuid NOT NULL REFERENCES church_module.program_offering(id),starts_at timestamptz,ends_at timestamptz,status text NOT NULL);
CREATE TABLE church_module.enrollment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),cohort_id uuid NOT NULL REFERENCES church_module.cohort(id),person_id uuid NOT NULL REFERENCES church_identity.person(id),status text NOT NULL);
CREATE TABLE church_module.service_team(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),name text NOT NULL,status text NOT NULL);
CREATE TABLE church_module.service_role(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),team_id uuid NOT NULL REFERENCES church_module.service_team(id),name text NOT NULL);
CREATE TABLE church_module.service_assignment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),person_id uuid NOT NULL REFERENCES church_identity.person(id),role_id uuid NOT NULL REFERENCES church_module.service_role(id),valid_from timestamptz NOT NULL,valid_to timestamptz);
CREATE TABLE church_module.event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),campus_id uuid REFERENCES church_tenant.campus(id),title text NOT NULL,starts_at timestamptz NOT NULL,status text NOT NULL);
CREATE TABLE church_module.registration(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),event_id uuid NOT NULL REFERENCES church_module.event(id),person_id uuid NOT NULL REFERENCES church_identity.person(id),status text NOT NULL);
CREATE TABLE church_module.community_mission(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),name text NOT NULL,duration_days integer,status text NOT NULL);
CREATE TABLE church_module.mission_participant(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),mission_id uuid NOT NULL REFERENCES church_module.community_mission(id),person_id uuid NOT NULL REFERENCES church_identity.person(id),status text NOT NULL);
CREATE TABLE church_module.notification_preference(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),person_id uuid NOT NULL REFERENCES church_identity.person(id),channel text NOT NULL,category text NOT NULL,enabled boolean NOT NULL DEFAULT true,quiet_policy jsonb);
CREATE TABLE church_module.content_item(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES church_tenant.church(id),type text NOT NULL,title text NOT NULL,body_ref text,status text NOT NULL,locale text);
COMMIT;
